#include <deque>
#include <iterator>
#include <iostream>

// Ambiguous, treated as FUNCTION DECLARATION:
// std::deque<int> c(std::istream_iterator<int>(), std::istream_iterator<int>()); 

int main() {
    // Fix 1: Using extra parentheses (less clean)
    std::deque<int> d1((std::istream_iterator<int>())); 

    // Fix 2: Using C++11 uniform initialization (preferred)
    std::deque<int> d2{std::istream_iterator<int>()}; 

    std::cout << d2.size() << "\n"; // d2 is an object, not a function
    return 0;
}
